public class GTreeTable<T> : JPanel where T : GTreeTableNode {
	private GTable table;
	private GTableFilterPanel<T> filterPanel;

	private GTreeTableModel<T> tableModel;

	public GTreeTable(GTreeTableModel<T> model) {
		tableModel = model;
		table = new GTable(tableModel);
		setLayout(new BorderLayout());

		addTableToPanel(table);

		table.addMouseListener(new _Anon_MouseAdapter_1());

		filterPanel = new(table, tableModel);
		add(filterPanel, BorderLayout.SOUTH);
	}

	/**
	 * Sort of a hack to allow extending classes the ability to add any wrappers around the GTable
	 * if desired
	 *
	 * @param table
	 * 		Table to add to the panel
	 */
	protected void addTableToPanel(GTable table) {
		add(new JScrollPane(table));
	}

