	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				int row = table.rowAtPoint(e.getPoint());
				int col = table.columnAtPoint(e.getPoint());
				GTreeTableNode selected = filterPanel.getSelectedItem();
				if (selected == null) {
					return;
				}
				if (table.getCellRenderer(row,
					col) is GTreeTableCellRenderer renderer) {
					Rectangle cellRect = table.getCellRect(row, col, false);

					if (renderer.inExpandIcon(selected, e.getX() - cellRect.x)) {
